{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-img-prompt",
  "version": "0.1.0",
  "description": "opencode plugin that renders your typed prompt as an image and sends it to the model instead of text, to cut input tokens on dense prompts.",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tokens",
    "vision",
    "ocr"
  ],
  "main": "plugin/img-prompt.ts",
  "exports": {
    ".": "./plugin/img-prompt.ts",
    "./server": {
      "import": "./plugin/img-prompt.ts",
      "config": {
        "minChars": 200
      }
    }
  },
  "files": [
    "plugin",
    "plugin/fonts/JetBrainsMono-Regular.ttf",
    "prompt-screenshot.nu",
    "prompt-ab-test.nu",
    "README.md"
  ],
  "engines": {
    "opencode": ">=1.1.0"
  },
  "scripts": {
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.1.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.1.12",
    "@types/node": "^22.13.9",
    "typescript": "^5.8.2"
  }
}
